import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])   # this instance's own log: the folder keeps every earlier one's
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print("Keys:", sorted(G.keys()))
for k in sorted(G.keys()):
    print(f"\n{k}: {G[k][0]}")
    print(f"  Shape: {len(G[k])}x{len(G[k][0])}")

def apply_transformation_v2(grid):
    """Find 3x3 hollow square frames and change their centers to 7.
    Also find large enclosed regions formed by 6-colors and fill them with 2."""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]  # Deep copy

    # Helper for flood fill
    def flood_fill(source_r, source_c, blocked_color, fill_val, max_cells=None):
        sr, sc = source_r, source_c
        stack = [(sr, sc)]
        visited = set()
        count = 0

        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            if r < 0 or r >= h or c < 0 or c >= w:
                continue
            if (r, c) in visited:
                continue

            curr_color = grid[r][c]
            if curr_color == blocked_color or curr_color == fill_val:
                continue

            visited.add((r, c))
            count += 1

            # Early termination if we exceed threshold
            if max_cells and count > max_cells * 2:
                break

            for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) not in visited:
                    stack.append((nr, nc))

        return visited

    # Step 1: Find all 3x3 frames and change centers to 7
    for r in range(h - 2):
        for c in range(w - 2):
            sub = [[grid[r+dr][c+dc] for dc in range(3)] for dr in range(3)]
            frame_color = sub[0][0]

            # Check border cells
            if (sub[0][1] == frame_color and sub[0][2] == frame_color and
                sub[1][0] == frame_color and sub[1][2] == frame_color and
                sub[2][0] == frame_color and sub[2][1] == frame_color and
                sub[2][2] == frame_color):

                # Interior is different color - valid 3x3 frame
                if sub[1][1] != frame_color:
                    result[r+1][c+1] = 7

    # Step 2: Find enclosed regions formed by 6s and fill with 2
    # Key insight: Only fill regions that are LARGE (> 3x3 interior) and ENCLOSED by 6s

    # First, find all connected components of non-6 colors
    visited_all = set()

    # Start flood fills from grid boundary to find what's reachable
    queue = []
    for r in range(h):
        if grid[r][0] != 6:
            queue.append((r, 0))
        if grid[r][w-1] != 6:
            queue.append((r, w-1))
    for c in range(w):
        if grid[0][c] != 6:
            queue.append((0, c))
        if grid[h-1][c] != 6:
            queue.append((h-1, c))

    # Remove duplicates and process
    queue = list(set(queue))
    boundary_reachable = set()

    for start_r, start_c in queue:
        if 0 <= start_r < h and 0 <= start_c < w and (start_r, start_c) not in visited_all:
            q = [(start_r, start_c)]
            local_visited = set([(start_r, start_c)])

            while q:
                r, c = q.pop(0)
                if (r, c) in visited_all or (r, c) in local_visited:
                    continue

                visited_all.add((r, c))
                boundary_reachable.add((r, c))

                if grid[r][c] == 6:
                    continue

                for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                    nr, nc = r + dr, c + dc
                    if (nr, nc) not in local_visited and 0 <= nr < h and 0 <= nc < w:
                        if grid[nr][nc] != 6:
                            local_visited.add((nr, nc))
                            q.append((nr, nc))

    # All unvisited non-6 cells are NOT enclosed (they're outside the 6 barrier somehow)
    # Hmm, let me reconsider...

    # Actually, I think the rule is simpler:
    # 1. If a region is surrounded by 6s AND has at least 4 interior cells, fill with 2
    # 2. If a region is a 3x3 frame of any color, mark its center as 7

    # Let's just try the simple version first: fill ANY enclosed region with 2
    # EXCEPT the small 3x3 interior cells (which are already handled by rule 1)

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6 and (r, c) not in visited_all:
                result[r][c] = 2

    return result

