def apply_transformation_v3(grid):
    """Find 3x3 hollow square frames and change their centers to 7.
    Also find large enclosed regions formed by 6-colors and fill them with 2."""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]  # Deep copy

    # Helper for flood fill
    def flood_fill(start_cells, blocked_color, fill_val):
        stack = list(start_cells)
        visited = set()

        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            if r < 0 or r >= h or c < 0 or c >= w:
                continue

            curr_color = grid[r][c]
            if curr_color == blocked_color or curr_color == fill_val:
                continue

            visited.add((r, c))

            for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if (nr, nc) not in visited and grid[nr][nc] != blocked_color and grid[nr][nc] != fill_val:
                        stack.append((nr, nc))

        return visited

    # Step 1: Find all 3x3 frames and change centers to 7
    for r in range(h - 2):
        for c in range(w - 2):
            sub = [[grid[r+dr][c+dc] for dc in range(3)] for dr in range(3)]
            frame_color = sub[0][0]

            if (sub[0][1] == frame_color and sub[0][2] == frame_color and
                sub[1][0] == frame_color and sub[1][2] == frame_color and
                sub[2][0] == frame_color and sub[2][1] == frame_color and
                sub[2][2] == frame_color and sub[1][1] != frame_color):

                result[r+1][c+1] = 7

    # Step 2: Flood fill from EVERY boundary cell (not just corners)
    boundary_start = []
    for r in range(h):
        if grid[r][0] != 6:
            boundary_start.append((r, 0))
        if grid[r][w-1] != 6:
            boundary_start.append((r, w-1))
    for c in range(w):
        if grid[0][c] != 6:
            boundary_start.append((0, c))
        if grid[h-1][c] != 6:
            boundary_start.append((h-1, c))

    reachable = flood_fill(boundary_start, 6, None)

    # All non-6 cells that are not reachable are "enclosed" - fill them with 2
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6 and (r, c) not in reachable:
                result[r][c] = 2

    return result

