def flood_fill_unreachable(grid, start_color=None):
    """
    Start from grid edges, flood fill through non-6 cells.
    Unvisited non-6 cells are potentially enclosed.

    Returns set of cells reachable from boundary.
    """
    h, w = len(grid), len(grid[0])
    reachable = set()

    # Queue all edge cells that are not 6
    queue = []
    visited_edges = set()

    for r in range(h):
        for c in [(0, w-1)]:
            if 0 <= c < w and grid[r][c] != 6:
                queue.append((r, c))
                visited_edges.add((r, c))

    for c in range(w):
        if grid[0][c] != 6:
            queue.append((0, c))
            visited_edges.add((0, c))
        if grid[h-1][c] != 6:
            queue.append((h-1, c))
            visited_edges.add((h-1, c))

    # Remove duplicates
    queue = list(set(queue))

    while queue:
        r, c = queue.pop(0)
        if (r, c) in reachable:
            continue

        if grid[r][c] == 6:
            continue

        reachable.add((r, c))

        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) not in reachable and grid[nr][nc] != 6:
                    queue.append((nr, nc))

    return reachable

