def find_connected_components(grid):
    """Find all connected components ignoring 6s."""
    h, w = len(grid), len(grid[0])
    visited = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6 and (r,c) not in visited:
                comp = [(r,c)]
                queue = [(r,c)]
                vis_comp = {(r,c)}

                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) in visited or (cr, cc) in vis_comp:
                        continue
                    visited.add((cr, cc))

                    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 6 and (nr,nc) not in vis_comp and (nr,nc) not in visited:
                            vis_comp.add((nr,nc))
                            queue.append((nr,nc))
                components.append(comp)

    return components

