def find_maximal_rectangles(grid):
    """
    Find all maximal rectangular loops in the grid.
    A maximal rectangular loop is a rectangle where all border cells have the same color C,
    and the rectangle cannot be expanded while maintaining property C on the new border.

    Returns list of dicts with 'rect', 'color', 'interior_cells'
    """
    h, w = len(grid), len(grid[0])
    rects = []

    # For each possible top-left corner and border color, expand to maximal rectangle
    for r1 in range(h):
        for c1 in range(w):
            color = grid[r1][c1]

            # Expand right and down
            max_r, max_c = r1, c1

            # How far right can we go?
            for c2 in range(c1 + 3, w):  # Need at least width 3
                if grid[r1][c2] != color:
                    break

            # How far down can we go?
            for r2 in range(r1 + 3, h):  # Need at least height 3
                if grid[r2][c1] != color:
                    break
                # Check top row continuity
                if any(grid[r1][c] != color for c in range(c1, c2+1)):
                    break

                # Check bottom row at this point
                if any(grid[r2][c] != color for c in range(c1, c2+1)):
                    continue

                # All borders OK
                # Interior must NOT all be color
                has_interior = False
                for rr in range(r1+1, r2):
                    if any(grid[rr][cc] == color for cc in range(c1+1, c2)):
                        has_interior = True
                        break
                if has_interior:
                    continue

            # This is a valid maximal rectangle (could simplify logic)
            # For now, just collect all valid rectangles and handle overlaps later
            pass

    # Simpler approach: find ALL rectangles where border is uniform color, filter to "maximal"
    all_valid = []

    for r1 in range(h):
        for c1 in range(w):
            for r2 in range(r1+2, h):
                for c2 in range(c1+2, w):
                    color = grid[r1][c1]

                    # Check border
                    valid = True
                    for c in range(c1, c2+1):
                        if grid[r1][c] != color or grid[r2][c] != color:
                            valid = False
                            break
                    if not valid:
                        continue
                    for r in range(r1, r2+1):
                        if grid[r][c1] != color or grid[r][c2] != color:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Interior exists and doesn't match border color
                    interior_all_same_color = True
                    for r in range(r1+1, r2):
                        for c in range(c1+1, c2):
                            if grid[r][c] == color:
                                interior_all_same_color = False
                                break
                        if not interior_all_same_color:
                            break

                    if interior_all_same_color:
                        all_valid.append({
                            'rect': (r1, c1, r2, c2),
                            'color': color,
                            'border_is_frame': interior_all_same_color
                        })

    return all_valid

