def rects_overlap_or_contain(r1, r2):
    """Check if two rectangles overlap or one contains the other."""
    def bbox_contains(rect1, rect2):
        # Check if rect2 is completely inside rect1
        t1, l1, b1, r1_c = rect1
        t2, l2, b2, r2_c = rect2
        return t1 <= t2 and l1 <= l2 and b1 >= b2 and r1_c >= r2_c

    def any_overlap(rect1, rect2):
        t1, l1, b1, r1_c = rect1
        t2, l2, b2, r2_c = rect2
        return not (t1 > b2 or b1 < t2 or l1 > r2_c or r1_c < l2)

    # Note: we consider borders as part of the rectangle for containment check
    return any_overlap(r1, r2)

