def apply_frame_filling_v2(grid):
    """
    Apply filling rules:
    1. Find all rectangular frames (uniform border, different interior)
    2. For each cell, find the LARGEST frame whose interior contains it
    3. Fill with 2 if frame color is 6, else fill with 7

    Returns a copy of the grid with fills applied.
    """
    h, w = len(grid), len(grid[0])
    # Track which frame (color) should fill each cell
    # Initialize as None (not in any frame interior)
    fill_assignments = {}

    # Find all valid rectangles
    rects = []
    for r1 in range(h):
        for c1 in range(w):
            for r2 in range(r1+2, h):
                for c2 in range(c1+2, w):
                    color = grid[r1][c1]

                    # Check border uniformity
                    valid_border = True
                    for c in range(c1, c2+1):
                        if grid[r1][c] != color or grid[r2][c] != color:
                            valid_border = False
                            break
                    if not valid_border:
                        continue
                    for r in range(r1, r2+1):
                        if grid[r][c1] != color or grid[r][c2] != color:
                            valid_border = False
                            break
                    if not valid_border:
                        continue

                    # Check that interior exists and isn't all the same color as border
                    interior_different = True
                    for r in range(r1+1, r2):
                        for c in range(c1+1, c2):
                            if grid[r][c] == color:
                                interior_different = False
                                break
                        if not interior_different:
                            break

                    if interior_different:
                        rect_interiors = set((rr, cc) for rr in range(r1+1, r2) for cc in range(c1+1, c2))
                        rects.append({
                            'rect': (r1, c1, r2, c2),
                            'height': r2-r1,
                            'width': c2-c1,
                            'area': (r2-r1)*(c2-c1),
                            'color': color,
                            'interiors': rect_interiors
                        })

    # Assign fills: larger area frames get priority
    # Sort by area descending
    sorted_rects = sorted(rects, key=lambda x: x['area'], reverse=True)

    # Process in order, marking cells that are already marked (don't override)
    for rect in sorted_rects:
        fill_color = 2 if rect['color'] == 6 else 7
        for cell in rect['interiors']:
            if cell not in fill_assignments:
                fill_assignments[cell] = fill_color

    # Apply fills to grid
    result = [row[:] for row in grid]
    for (r, c), fill_color in fill_assignments.items():
        result[r][c] = fill_color

    return result, fill_assignments

