                # Verify complete lines
                valid = True
                for c in range(c1, c_end+1):
                    if grid[r1][c] != color or grid[r2][c] != color:
                        valid = False
                        break

                if not valid:
                    continue

                # Check vertical sides
                valid_sides = True
                for r in range(r1, r2+1):
                    if grid[r][c1] != color or grid[r][c_end] != color:
                        valid_sides = False
