def apply_transform(grid):
    """Apply full transformation with proper fill colors"""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find all frames and mark their interiors with 0 (to-fill)
    frame_colors = {1, 3, 4, 5, 6}

    frame_info = []  # Store frame info for fill color decision

    for r1 in range(h):
        for c1 in range(w - 4):
            color = grid[r1][c1]
            if color not in frame_colors:
                continue

            c_end = c1
            while c_end < w-1 and grid[r1][c_end+1] == color:
                c_end += 1

            if c_end - c1 + 1 < 5:
                continue

            found_bottom = False
            for r2 in range(r1+3, h):
                if grid[r2][c1] != color or grid[r2][c_end] != color:
                    continue

                valid = True
                for c in range(c1, c_end+1):
                    if grid[r1][c] != color or grid[r2][c] != color:
                        valid = False
                        break

                if not valid:
                    continue

                valid_sides = True
                for r in range(r1, r2+1):
                    if grid[r][c1] != color or grid[r][c_end] != color:
                        valid_sides = False
                        break

                if valid_sides:
                    # Fill interior with 0 as marker
                    for r in range(r1+1, r2):
                        for c in range(c1+1, c_end):
                            if result[r][c] != color:
                                result[r][c] = 0

                    # Record frame info
                    frame_info.append({'color': color, 'bbox': (r1, c1, r2, c_end)})

                    found_bottom = True
                    break
            if found_bottom:
                break

    # Now assign fill colors based on proximity to green (6)
    # If any 9-region inside a frame is adjacent to green, fill that frame's interior with 2
    # Otherwise fill with 7

    green_positions = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    for frame in frame_info:
        bbox = frame['bbox']
        r1, c1, r2, c2 = bbox

        # Check if this frame's interior is adjacent to any green pixel
        has_green_adjacency = False
        for r in range(r1+1, r2):
            for c in range(c1+1, c2):
                # Check if result[r][c] is 0 (inside frame)
                if result[r][c] == 0:
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 6:
                            has_green_adjacency = True
                            break
                if has_green_adjacency:
                    break
            if has_green_adjacency:
                break

        fill_color = 2 if has_green_adjacency else 7

        # Apply fill
        for r in range(r1+1, r2):
            for c in range(c1+1, c2):
                if result[r][c] == 0:
                    result[r][c] = fill_color

    return result

